// ratelimit_test.go
package ratelimit

import (
	"testing"
	"time"
)

type fakeClock struct{ t time.Time }

func (f *fakeClock) Now() time.Time { return f.t }
func (f *fakeClock) advance(d time.Duration) {
	f.t = f.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	if _, err := New(0, 1, nil); err == nil {
		t.Error("expected error for zero rate")
	}
	if _, err := New(1, 0, nil); err == nil {
		t.Error("expected error for zero burst")
	}
	if _, err := New(-1, -1, nil); err == nil {
		t.Error("expected error for negative config")
	}
	if _, err := New(1, 1, nil); err != nil {
		t.Errorf("unexpected error: %v", err)
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)

	tests := []struct {
		name    string
		rate    float64
		burst   int64
		steps   []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name:  "burst exhausted then refills",
			rate:  1, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{0, 1, false},
				{time.Second, 1, true},
				{0, 1, false},
				{2 * time.Second, 2, true},
			},
		},
		{
			name:  "tokens cap at burst",
			rate:  10, burst: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},
				{10 * time.Second, 2, true}, // only 2 accumulated
				{0, 1, false},
			},
		},
		{
			name:  "fractional refill",
			rate:  2, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 1, false},
				{250 * time.Millisecond, 1, false}, // 0.5 tokens
				{250 * time.Millisecond, 1, true},  // 1.0 tokens
			},
		},
		{
			name:  "zero request always allowed",
			rate:  1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 0, true},
				{0, 1, false},
			},
		},
		{
			name:  "negative request denied",
			rate:  1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, -1, false},
				{0, 1, true},
			},
		},
		{
			name:  "time going backwards does not grant tokens",
			rate:  1, burst: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{time.Second, 0, true},
				{-time.Second, 1, false},
				{2 * time.Second, 1, true},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			fc := &fakeClock{t: base}
			l, err := New(tt.rate, tt.burst, fc)
			if err != nil {
				t.Fatalf("New: %v", err)
			}
			for i, s := range tt.steps {
				fc.advance(s.advance)
				if got := l.AllowN(fc.t, s.n); got != s.want {
					t.Errorf("step %d: AllowN(n=%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllowUsesClock(t *testing.T) {
	fc := &fakeClock{t: time.Unix(0, 0)}
	l, err := New(1, 1, fc)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	if !l.Allow() {
		t.Fatal("first Allow should succeed")
	}
	if l.Allow() {
		t.Fatal("second Allow should fail")
	}
	fc.advance(time.Second)
	if !l.Allow() {
		t.Fatal("Allow after refill should succeed")
	}
}

func TestConcurrentUse(t *testing.T) {
	fc := &fakeClock{t: time.Unix(0, 0)}
	l, err := New(1000, 100, fc)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	var mu struct {
		sync.Mutex
		granted int
	}
	done := make(chan struct{})
	for i := 0; i < 50; i++ {
		go func() {
			defer func() { done <- struct{}{} }()
			for j := 0; j < 100; j++ {
				if l.AllowN(fc.t, 1) {
					mu.Lock()
					mu.granted++
					mu.Unlock()
				}
			}
		}()
	}
	for i := 0; i < 50; i++ {
		<-done
	}
	if mu.granted > 100 {
		t.Errorf("granted %d tokens, burst is 100", mu.granted)
	}
}
